    int? total,
  }) =>
      WeeklyVerificationFeature(
        tanggal: tanggal ?? this.tanggal,
        hari: hari ?? this.hari,
        total: total ?? this.total,
      );

  String get shortDay {
    if (hari == null) return '';
    if (hari!.length < 3) return hari!;
    return hari!.substring(0, 3);
  }
}

